type Rentention interface {
	LogRender(ctx context.Context, req *EmptyReq) (r *EmptyResp, err error)

	OverviewRender(ctx context.Context, req *EmptyReq) (r *EmptyResp, err error)

	RealDataRender(ctx context.Context, req *EmptyReq) (r *EmptyResp, err error)
	//  用于提供前后端分离接口
	SystemRealtimeScore(ctx context.Context, req *EmptyReq) (r *RealtimeScoreResp, err error)
	// 系统分数列表
	SystemDailyScore(ctx context.Context, req *DailyScoreReq) (r *DailyScoreResp, err error)
	// 错误率，基于Nginx日志
	SystemDailyApiFailureInfo(ctx context.Context, req *DailyApiFailureInfoReq) (r *ApiFailureInfoResp, err error)

	SystemDailyApiFailureDetail(ctx context.Context, req *DailyApiFailureDetailReq) (r *ApiFailureDetailResp, err error)
	// 慢查询率，基于业务日志
	SystemDailyApiSlowInfo(ctx context.Context, req *DailyApiSlowInfoReq) (r *ApiSlowInfoResp, err error)
	// 探针错误率，基于探针日志
	SystemDailyApiCost(ctx context.Context, req *ApiProbeResp) (r *ApiProbeResp, err error)

	SystemProbeLogDetail(ctx context.Context, req *ProbeLogDetailReq) (r *ProbeLogDetailResp, err error)
	// 全链路日志
	SystemEndToEndTraceLogs(ctx context.Context, req *EndToEndTraceReq) (r *EndToEndTraceResp, err error)
	// Traceback日志列表
	SysteTracebackLogs(ctx context.Context, req *TracebackReq) (r *TracebackResp, err error)
	// 用于提供缓存数据库接口
	SystemDbTidy(ctx context.Context, req *DbTidyReq) (r *DbRefreshResp, err error)

	SystemDbRefresh(ctx context.Context, req *DbRefreshReq) (r *DbRefreshResp, err error)

	WriteProbeLogs(ctx context.Context, req *WriteProbeReq) (r *WriteProbeResp, err error)

	SystemRealData(ctx context.Context, req *RealDataReq) (r *RealDataResp, err error)
}

